   714  // This encapsulates where the parser is in the current source file.
   715  struct ParserState {
   716    ParserState()
   717        : cursor_(nullptr),
   718          line_start_(nullptr),
   719          line_(0),
   720          token_(-1),
   721          attr_is_trivial_ascii_string_(true) {}
   722
   723   protected:
   724    void ResetState(const char *source) {
   725      cursor_ = source;
   726      line_ = 0;
   727      MarkNewLine();
   728    }
   729
   730    void MarkNewLine() {
   731      line_start_ = cursor_;
   732      line_ += 1;
   733    }
   734
   735    int64_t CursorPosition() const {
   736      FLATBUFFERS_ASSERT(cursor_ && line_start_ && cursor_ >= line_start_);
   737      return static_cast<int64_t>(cursor_ - line_start_);
   738    }
   739
   740    const char *cursor_;
   741    const char *line_start_;
   742    int line_;  // the current line being parsed
   743    int token_;
   744
   745    // Flag: text in attribute_ is true ASCII string without escape
   746    // sequences. Only printable ASCII (without [\t\r\n]).
   747    // Used for number-in-string (and base64 string in future).
   748    bool attr_is_trivial_ascii_string_;
   749    std::string attribute_;
   750    std::vector<std::string> doc_comment_;
   751  };
