   753  // A way to make error propagation less error prone by requiring values to be
   754  // checked.
   755  // Once you create a value of this type you must either:
   756  // - Call Check() on it.
   757  // - Copy or assign it to another value.
   758  // Failure to do so leads to an assert.
   759  // This guarantees that this as return value cannot be ignored.
   760  class CheckedError {
   761   public:
   762    explicit CheckedError(bool error)
   763        : is_error_(error), has_been_checked_(false) {}
   764
   765    CheckedError &operator=(const CheckedError &other) {
   766      is_error_ = other.is_error_;
   767      has_been_checked_ = false;
   768      other.has_been_checked_ = true;
   769      return *this;
   770    }
   771
   772    CheckedError(const CheckedError &other) {
   773      *this = other;  // Use assignment operator.
   774    }
   775
   776    ~CheckedError() { FLATBUFFERS_ASSERT(has_been_checked_); }
   777
   778    bool Check() {
   779      has_been_checked_ = true;
   780      return is_error_;
   781    }
   782
   783   private:
   784    bool is_error_;
   785    mutable bool has_been_checked_;
   786  };
