   789  // assurance:
   790  // clang-format off
   791  #ifdef __GNUC__
   792  #define FLATBUFFERS_CHECKED_ERROR CheckedError \
   793            __attribute__((warn_unused_result))
   794  #else
   795  #define FLATBUFFERS_CHECKED_ERROR CheckedError
   796  #endif
